import express from 'express';
import cookieParser from 'cookie-parser';
import morgan from 'morgan';
import mongoSanitize from 'express-mongo-sanitize';
import hpp from 'hpp';
import path from 'path';
import { fileURLToPath } from 'url';
import env from './config/env.js';
import { helmetMiddleware, corsMiddleware, csrfProtection } from './middleware/security.js';
import apiRoutes from './routes/index.js';
import { verifyAccessToken } from './utils/jwt.js';
import { errorHandler, notFound } from './middleware/errorHandler.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const app = express();

app.set('trust proxy', 1);

app.use(helmetMiddleware);
app.use(corsMiddleware);

// Add performance and security headers
app.use((req, res, next) => {
  res.setHeader('X-DNS-Prefetch-Control', 'on');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  next();
});
// Reset links and other query parameters may contain secrets; log only the path.
morgan.token('safe-path', req => req.path);
app.use(morgan(':method :safe-path :status :response-time ms'));
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));
app.use(cookieParser());
app.use('/api', csrfProtection);
app.use(mongoSanitize());
app.use(hpp());

// Protect admin pages in browser requests
app.use((req, res, next) => {
  const url = req.originalUrl;
  
  // Skip API, uploads, static files (files with extensions)
  if (url.startsWith('/api') || url.startsWith('/uploads') || url.includes('.')) {
    return next();
  }

  // Intercept any admin page requests based on secret path
  if (url.startsWith(env.ADMIN_SECRET_PATH)) {
    const token = req.cookies?.accessToken;
    let user = null;

    if (token) {
      try {
        user = verifyAccessToken(token);
      } catch (err) {
        // Token is invalid/expired; clear it and treat user as unauthenticated
        res.clearCookie('accessToken');
        // Keep refresh cookie so the client can renew an expired access session.
      }
    }

    // Case 1: Logged-in user is a normal user (role !== 'admin')
    if (user && user.role !== 'admin') {
      res.status(403);
      return res.send(`
        <!DOCTYPE html>
        <html lang="en">
        <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>403 Forbidden</title>
          <style>
            body {
              background-color: #0a0f18;
              color: #ffffff;
              font-family: 'Inter', system-ui, -apple-system, sans-serif;
              display: flex;
              flex-direction: column;
              align-items: center;
              justify-content: center;
              height: 100vh;
              margin: 0;
              text-align: center;
            }
            .container {
              max-width: 400px;
              padding: 2rem;
              border: 1px solid #c2a649;
              background-color: #111827;
              border-radius: 12px;
              box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
            }
            h1 {
              color: #f59e0b;
              font-size: 2.2rem;
              margin-bottom: 1rem;
            }
            p {
              color: #9ca3af;
              font-size: 1rem;
              line-height: 1.5;
            }
            .spinner {
              border: 3px solid rgba(245, 158, 11, 0.1);
              width: 36px;
              height: 36px;
              border-radius: 50%;
              border-left-color: #f59e0b;
              animation: spin 1s linear infinite;
              margin: 2rem auto 0;
            }
            @keyframes spin {
              0% { transform: rotate(0deg); }
              100% { transform: rotate(360deg); }
            }
          </style>
          <script>
            setTimeout(function() {
              window.location.href = '/';
            }, 3000);
          </script>
        </head>
        <body>
          <div class="container">
            <h1>403 Forbidden</h1>
            <p>Access denied. Normal users are not allowed to access the admin portal.</p>
            <p>Redirecting to homepage...</p>
            <div class="spinner"></div>
          </div>
        </body>
        </html>
      `);
    }

    // Case 2: Not authenticated and trying to access restricted admin pages (anything except login)
    if (!user && url !== `${env.ADMIN_SECRET_PATH}/login`) {
      return res.redirect(`${env.ADMIN_SECRET_PATH}/login`);
    }
  }

  next();
});

app.use('/uploads', express.static(path.join(__dirname, 'uploads')));

app.use('/api', apiRoutes);
app.use('/api', notFound);
app.use('/api', errorHandler);

export default app;

import asyncHandler from '../utils/asyncHandler.js';
import ApiResponse from '../utils/ApiResponse.js';
import User from '../models/User.js';
import ApiError from '../utils/ApiError.js';
import { hashPassword, comparePassword } from '../utils/password.js';
import {
  registerUser,
  loginUser,
  loginWithPassword,
  sendLoginOtp,
  verifyLoginOtp,
  refreshAccessToken,
  logoutUser,
  signOutAllDevices,
  forgotPassword,
  resetPassword,
  setAuthCookies,
  formatAuthResponse,
} from '../services/authService.js';
import { logAudit } from '../services/auditService.js';

export const register = asyncHandler(async (req, res) => {
  const result = await registerUser(req.body);
  res.status(201).json({
    success: true,
    message: 'Account created. Verify the OTP sent to your email to continue.',
    data: result,
  });
});

export const login = asyncHandler(async (req, res) => {
  const tokens = await loginWithPassword(req.body.email, req.body.password, 'user');
  setAuthCookies(res, tokens.accessToken, tokens.refreshToken);
  res.json(formatAuthResponse(tokens));
});

export const adminLogin = asyncHandler(async (req, res) => {
  const tokens = await loginWithPassword(req.body.email, req.body.password, 'admin');
  setAuthCookies(res, tokens.accessToken, tokens.refreshToken);
  await logAudit({ userId: tokens.user._id, action: 'ADMIN_LOGIN', req });
  res.json(formatAuthResponse(tokens));
});

// Email + password login for users who set a password
export const loginPassword = asyncHandler(async (req, res) => {
  const tokens = await loginWithPassword(req.body.email, req.body.password);
  setAuthCookies(res, tokens.accessToken, tokens.refreshToken);
  res.json(formatAuthResponse(tokens));
});

export const sendOtp = asyncHandler(async (req, res) => {
  const role = req.body.role === 'admin' ? 'admin' : 'user';
  const result = await sendLoginOtp(req.body.identifier, role);
  ApiResponse.success(res, 200, 'OTP sent successfully', result);
});

export const verifyOtp = asyncHandler(async (req, res) => {
  const role = req.body.role === 'admin' ? 'admin' : 'user';
  const tokens = await verifyLoginOtp(req.body.identifier, req.body.otp, role);
  setAuthCookies(res, tokens.accessToken, tokens.refreshToken);
  if (role === 'admin') {
    await logAudit({ userId: tokens.user._id, action: 'ADMIN_LOGIN', req });
  }
  res.json(formatAuthResponse(tokens));
});

export const refresh = asyncHandler(async (req, res) => {
  const refreshToken = req.cookies?.refreshToken || req.body.refreshToken;
  const tokens = await refreshAccessToken(refreshToken);
  setAuthCookies(res, tokens.accessToken, tokens.refreshToken);
  ApiResponse.success(res, 200, 'Token refreshed', formatAuthResponse(tokens));
});

export const logout = asyncHandler(async (req, res) => {
  await logoutUser(req.user?.id, res);
  ApiResponse.success(res, 200, 'Logged out successfully');
});

export const signOutAll = asyncHandler(async (req, res) => {
  await signOutAllDevices(req.user?.id, res);
  ApiResponse.success(res, 200, 'Signed out from all devices successfully');
});

export const forgotPasswordHandler = asyncHandler(async (req, res) => {
  const result = await forgotPassword(req.body.email);
  ApiResponse.success(res, 200, result.message);
});

export const resetPasswordHandler = asyncHandler(async (req, res) => {
  const password = req.body.newPassword || req.body.password;
  const result = await resetPassword(req.body.token, password);
  ApiResponse.success(res, 200, result.message);
});

export const getProfile = asyncHandler(async (req, res) => {
  const user = await User.findById(req.user.id);
  if (!user) throw new ApiError(404, 'User not found');
  ApiResponse.success(res, 200, 'Profile retrieved', user);
});

export const updateProfile = asyncHandler(async (req, res) => {
  const user = await User.findById(req.user.id).select('+password');
  if (!user) throw new ApiError(404, 'User not found');

  if (req.body.name) user.name = req.body.name;
  if (req.body.phone && req.body.phone !== user.phone) { user.phone = req.body.phone; user.phoneVerified = false; }
  if (req.body.password) {
    if (user.password && !(await comparePassword(req.body.currentPassword || '', user.password))) throw new ApiError(403, 'Current password is required');
    user.password = await hashPassword(req.body.password);
    user.refreshToken = undefined;
    user.sessionVersion = (user.sessionVersion || 0) + 1;
  }
  if (req.body.avatar) user.avatar = req.body.avatar;

  await user.save();
  ApiResponse.success(res, 200, 'Profile updated', user);
});

import env from '../config/env.js';
import ApiError from '../utils/ApiError.js';
import logger from '../utils/logger.js';

export const notFound = (req, _res, next) => {
  next(new ApiError(404, `Route not found: ${req.method} ${req.path}`));
};

export const errorHandler = (err, req, res, _next) => {
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal server error';
  let errors = err.errors || [];

  if (err.name === 'ValidationError') {
    statusCode = 400;
    message = 'Validation error';
    errors = Object.values(err.errors).map((e) => ({ field: e.path, message: e.message }));
  }

  if (err.code === 11000) {
    statusCode = 400;
    message = 'Duplicate field value';
    const field = Object.keys(err.keyPattern || {})[0];
    errors = [{ field, message: `${field} already exists` }];
  }

  if (err.name === 'CastError') {
    statusCode = 400;
    message = 'Invalid ID format';
  }

  if (['MongoNetworkError', 'MongoServerSelectionError', 'MongooseServerSelectionError', 'MongoNotConnectedError'].includes(err.name) || /bufferCommands = false/.test(message)) {
    statusCode = 503;
    message = 'Database temporarily unavailable. Please retry shortly.';
  }
  if (err.name === 'MulterError') { statusCode = 400; message = 'Upload exceeds file size or count limits'; }
  if (statusCode >= 500) {
    logger.error('Request failed', {
      path: req.path,
      method: req.method,
      errorType: err.name,
    });
  }

  if (statusCode === 500) { message = 'Internal server error'; errors = []; }
  res.status(statusCode).json({
    success: false,
    message,
    ...(errors.length > 0 && { errors }),
  });
};

import { Router } from 'express';
import * as contentController from '../controllers/contentController.js';
import { validate } from '../middleware/validate.js';
import { adminOnly } from '../middleware/auth.js';
import {
  serviceValidator,
  testimonialValidator,
  mongoIdParam,
} from '../validators/contentValidators.js';

const router = Router();

router.get('/', contentController.getServices);
router.post('/', adminOnly, serviceValidator, validate, contentController.createService);
router.put('/:id', adminOnly, mongoIdParam, serviceValidator, validate, contentController.updateService);
router.delete('/:id', adminOnly, mongoIdParam, validate, contentController.deleteService);

export default router;

import crypto from 'crypto';
import User from '../models/User.js';
import Otp from '../models/Otp.js';
import env from '../config/env.js';
import ApiError from '../utils/ApiError.js';
import {
  generateAccessToken,
  generateRefreshToken,
  verifyRefreshToken,
  verifyAccessToken,
  getTokenPayload,
} from '../utils/jwt.js';
import { hashPassword, comparePassword } from '../utils/password.js';
import { sendLoginOtpEmail, sendPasswordResetEmail } from './emailService.js';
import { sendLoginOtpPhone } from './phoneOtpService.js';
import logger from '../utils/logger.js';

const COOKIE_OPTIONS = {
  httpOnly: true,
  secure: env.IS_PRODUCTION,
  sameSite: process.env.COOKIE_SAME_SITE === 'none' && env.IS_PRODUCTION ? 'none' : 'lax',
  path: '/',
};

if (!env.IS_PRODUCTION) {
  logger.warn(
    'Auth cookies are set with secure=false and sameSite=lax (IS_PRODUCTION=false). ' +
      'Enable IS_PRODUCTION=true for any publicly accessible deployment.',
    { cookieSecure: false }
  );
}

export const setAuthCookies = (res, accessToken, refreshToken) => {
  res.cookie('accessToken', accessToken, { ...COOKIE_OPTIONS, maxAge: Math.max(0, verifyAccessToken(accessToken).exp * 1000 - Date.now()) });
  res.cookie('refreshToken', refreshToken, { ...COOKIE_OPTIONS, maxAge: Math.max(0, verifyRefreshToken(refreshToken).exp * 1000 - Date.now()) });
};

export const clearAuthCookies = (res) => {
  res.clearCookie('accessToken', COOKIE_OPTIONS);
  res.clearCookie('refreshToken', COOKIE_OPTIONS);
};

const handleFailedLogin = async (user) => {
  user.loginAttempts = (user.loginAttempts || 0) + 1;
  if (user.loginAttempts >= env.MAX_LOGIN_ATTEMPTS) {
    user.lockUntil = new Date(Date.now() + env.LOCKOUT_DURATION_MS);
    logger.warn('Account locked due to failed login attempts', { email: user.email });
  }
  await user.save();
};

const resetLoginAttempts = async (user) => {
  if (user.loginAttempts || user.lockUntil) {
    user.loginAttempts = 0;
    user.lockUntil = undefined;
    await user.save();
  }
};

const issueTokens = async (user) => {
  const payload = getTokenPayload(user);
  const accessToken = generateAccessToken(payload);
  const refreshToken = generateRefreshToken(payload);
  user.refreshToken = hashOtp(refreshToken);
  user.lastLogin = new Date();
  await user.save();
  return { accessToken, refreshToken, user };
};

const normalizeIdentifier = (identifier = '') => identifier.trim().toLowerCase();
const getOtpChannel = (identifier) => (identifier.includes('@') ? 'email' : 'phone');
const hashOtp = (otp) => crypto.createHash('sha256').update(otp).digest('hex');
const createOtp = () => String(crypto.randomInt(100000, 1000000));

const findUserByIdentifier = (identifier) => {
  const normalized = normalizeIdentifier(identifier);
  return User.findOne({
    $or: [{ email: normalized }, { phone: normalized }],
  }).select('+loginAttempts +lockUntil +password');
};

export const registerUser = async ({ name, firstName, lastName, email, phone, password, profileImage }) => {
  const normalizedEmail = normalizeIdentifier(email);
  const existing = await User.findOne({ email: normalizedEmail });
  if (existing) {
    if (existing.isVerified || existing.role !== 'user') throw new ApiError(409, 'User with this email already exists');
    // Resend without replacing the existing account's identity or password.
    return sendLoginOtp(normalizedEmail, 'user');
  }

  const resolvedName = name || `${firstName || ''} ${lastName || ''}`.trim();
  const hashed = password ? await hashPassword(password) : undefined;
  const user = await User.create({
    name: resolvedName,
    firstName,
    lastName,
    email: normalizedEmail,
    phone,
    password: hashed,
    profileImage,
    role: 'user',
    isVerified: false,
  });

  // Send real verification OTP to email
  try {
    await sendLoginOtp(normalizedEmail, 'user');
    logger.info('User registered and verification OTP sent', { email: user.email });
    return {
      user,
      otpRequired: true,
      identifier: user.email,
      channel: 'email',
      cooldownSeconds: 60,
      expiresInSeconds: 300,
    };
  } catch (otpErr) {
    logger.error('Registration verification delivery failed; pending account retained');
    if (otpErr.statusCode === 429) throw otpErr;
    throw new ApiError(503, 'Account pending verification. Email delivery is temporarily unavailable. Retry registration or request another OTP.');
  }
};

export const loginUser = async () => {
  throw new ApiError(410, 'Password login has been disabled. Please use OTP login.');
};

/**
 * Email + password login. User must have set a password during or after registration.
 * Supports both 'user' and 'admin' roles with brute-force lockout safeguards.
 */
export const loginWithPassword = async (email, password, expectedRole = 'user') => {
  const normalizedEmail = normalizeIdentifier(email);
  const user = await User.findOne({ email: normalizedEmail }).select('+loginAttempts +lockUntil +password');

  if (!user || user.role !== expectedRole) throw new ApiError(401, 'Invalid email or password');
  if (user.blocked) throw new ApiError(403, 'Your account has been blocked');
  if (user.isActive === false) throw new ApiError(403, 'Your account is inactive');
  if (user.isLocked()) throw new ApiError(423, 'Account temporarily locked. Try again later.');
  if (!user.password) {
    throw new ApiError(400, 'This account uses OTP login only. Please use the OTP option.');
  }

  const valid = await comparePassword(password, user.password);
  if (!valid) {
    await handleFailedLogin(user);
    throw new ApiError(401, 'Invalid email or password');
  }

  if (!user.isVerified) {
    await sendLoginOtp(normalizedEmail, expectedRole);
    throw new ApiError(403, 'Email not verified. A verification OTP has been sent to your email. Please verify to continue.');
  }

  await resetLoginAttempts(user);
  const tokens = await issueTokens(user);
  logger.info(`${expectedRole === 'admin' ? 'Admin' : 'User'} logged in with password`, { email: user.email });
  return tokens;
};

export const sendLoginOtp = async (identifier, expectedRole = 'user') => {
  const normalized = normalizeIdentifier(identifier);
  const channel = getOtpChannel(normalized);
  const user = await findUserByIdentifier(normalized);

  if (channel === 'phone' && !user?.phoneVerified) throw new ApiError(403, 'Use email login until phone ownership has been verified');

  if (!user || user.role !== expectedRole) {
    logger.warn('OTP requested for invalid account', { identifier: normalized, role: expectedRole });
    throw new ApiError(401, 'No matching account found for this login type. Please check your email or register a new account.');
  }

  if (user.blocked) throw new ApiError(403, 'Your account has been blocked');
  if (user.isActive === false) throw new ApiError(403, 'Your account is inactive');
  if (user.isLocked()) throw new ApiError(423, 'Account temporarily locked. Try again later.');

  const existingOtp = await Otp.findOne({ identifier: normalized, role: expectedRole }).select('+otpHash');
  if (existingOtp && existingOtp.expiresAt > new Date()) {
    const secondsSinceLastSend = (Date.now() - existingOtp.lastSentAt.getTime()) / 1000;
    if (secondsSinceLastSend < 60) {
      const waitSec = Math.ceil(60 - secondsSinceLastSend);
      throw new ApiError(429, `Please wait ${waitSec} seconds before requesting another OTP`);
    }
    if (existingOtp.resendCount >= 5) {
      throw new ApiError(429, 'Maximum OTP resend limit reached. Try again after 5 minutes.');
    }
  }

  const otp = createOtp();
  await Otp.findOneAndUpdate(
    { identifier: normalized, role: expectedRole },
    {
      identifier: normalized,
      channel,
      role: expectedRole,
      otpHash: hashOtp(otp),
      attempts: 0,
      resendCount: existingOtp && existingOtp.expiresAt > new Date() ? existingOtp.resendCount + 1 : 0,
      lastSentAt: new Date(),
      expiresAt: new Date(Date.now() + 5 * 60 * 1000),
    },
    { upsert: true, returnDocument: 'after', setDefaultsOnInsert: true, runValidators: true }
  );

  // Deliver real OTP via email or phone
  try {
    if (channel === 'email') {
      await sendLoginOtpEmail(user, otp);
    } else if (channel === 'phone') {
      await sendLoginOtpPhone(user, normalized, otp);
    }
  } catch (sendErr) {
    // Invalidate the unreached OTP from DB so user isn't stuck with unreachable code
    await Otp.deleteMany({ identifier: normalized, role: expectedRole, otpHash: hashOtp(otp) });
    logger.error('Failed to deliver OTP');
    throw new ApiError(503, 'Verification delivery temporarily unavailable. Please request another OTP shortly.');
  }

  logger.info('OTP successfully sent', { identifier: normalized, role: expectedRole, channel });

  return {
    otpRequired: true,
    identifier: normalized,
    channel,
    cooldownSeconds: 60,
    expiresInSeconds: 300,
  };
};

export const verifyLoginOtp = async (identifier, otp, expectedRole = 'user') => {
  const normalized = normalizeIdentifier(identifier);
  const user = await findUserByIdentifier(normalized);

  if (!user || user.role !== expectedRole) throw new ApiError(401, 'Invalid or expired OTP');
  if (user.blocked) throw new ApiError(403, 'Your account has been blocked');
  if (user.isActive === false) throw new ApiError(403, 'Your account is inactive');
  if (user.isLocked()) throw new ApiError(423, 'Account temporarily locked. Try again later.');
  if (getOtpChannel(normalized) === 'phone' && (!user.isVerified || !user.phoneVerified)) throw new ApiError(403, 'Verify email and phone ownership before using phone login');

  const otpRecord = await Otp.findOne({ identifier: normalized, role: expectedRole }).select('+otpHash');
  if (!otpRecord || otpRecord.expiresAt < new Date()) {
    await Otp.deleteMany({ identifier: normalized, role: expectedRole });
    throw new ApiError(401, 'Invalid or expired OTP');
  }

  if (otpRecord.attempts >= 5) {
    await handleFailedLogin(user);
    await Otp.deleteMany({ identifier: normalized, role: expectedRole });
    throw new ApiError(429, 'Maximum OTP attempts reached. Please request a new OTP.');
  }

  if (otpRecord.otpHash !== hashOtp(String(otp))) {
    await Otp.updateOne({ _id: otpRecord._id, otpHash: otpRecord.otpHash }, { $inc: { attempts: 1 } });
    await handleFailedLogin(user);
    throw new ApiError(401, 'Invalid OTP');
  }

  await resetLoginAttempts(user);
  const consumed = await Otp.findOneAndDelete({ _id: otpRecord._id, otpHash: hashOtp(String(otp)), attempts: { $lt: 5 }, expiresAt: { $gt: new Date() } });
  if (!consumed) throw new ApiError(401, 'Invalid or expired OTP');
  user.isVerified = true;
  const tokens = await issueTokens(user);
  logger.info('User logged in with OTP', { email: user.email, role: user.role });
  return tokens;
};

export const refreshAccessToken = async (refreshToken) => {
  if (!refreshToken) throw new ApiError(401, 'Refresh token required');

  let decoded;
  try {
    decoded = verifyRefreshToken(refreshToken);
  } catch {
    throw new ApiError(403, 'Invalid or expired refresh token');
  }

  const user = await User.findById(decoded.id).select('+refreshToken');
  if (!user || user.refreshToken !== hashOtp(refreshToken) || user.blocked || user.isActive === false || !user.isVerified) {
    throw new ApiError(403, 'Invalid refresh token');
  }

  const payload = getTokenPayload(user);
  const accessToken = generateAccessToken(payload);
  const newRefreshToken = generateRefreshToken(payload);
  const rotated = await User.findOneAndUpdate({ _id: user._id, refreshToken: hashOtp(refreshToken) }, { refreshToken: hashOtp(newRefreshToken) }, { new: true });
  if (!rotated) throw new ApiError(403, 'Refresh token already used');

  return { accessToken, refreshToken: newRefreshToken, user };
};

export const logoutUser = async (userId, res) => {
  if (userId) {
    await User.findByIdAndUpdate(userId, { $set: { refreshToken: null }, $inc: { sessionVersion: 1 } });
  }
  clearAuthCookies(res);
};

export const signOutAllDevices = async (userId, res) => {
  if (userId) {
    await User.findByIdAndUpdate(userId, { $set: { refreshToken: null }, $inc: { sessionVersion: 1 } });
    logger.info('All sessions signed out', { userId });
  }
  clearAuthCookies(res);
};

export const forgotPassword = async (email) => {
  const user = await User.findOne({ email });
  if (!user) return { message: 'If an account exists, a reset link has been sent.' };

  const token = crypto.randomBytes(32).toString('hex');
  user.resetToken = crypto.createHash('sha256').update(token).digest('hex');
  user.resetTokenExpiry = new Date(Date.now() + 3600000);
  await user.save();

  const resetLink = `${env.CLIENT_URL}/reset-password?token=${token}`;
  try {
    await sendPasswordResetEmail(user, resetLink);
  } catch (sendErr) {
    logger.warn('Password reset email delivery failed');
    throw new ApiError(503, 'Password reset delivery unavailable. Please try again shortly.');
  }

  logger.info('Password reset requested', { email });
  return { message: 'If an account exists, a reset link has been sent.' };
};

export const resetPassword = async (token, newPassword) => {
  const hashedToken = crypto.createHash('sha256').update(token).digest('hex');
  const user = await User.findOne({
    resetToken: hashedToken,
    resetTokenExpiry: { $gt: new Date() },
  }).select('+password +resetToken +resetTokenExpiry');

  if (!user) throw new ApiError(400, 'Invalid or expired password reset token');

  user.password = await hashPassword(newPassword);
  user.resetToken = undefined;
  user.resetTokenExpiry = undefined;
  user.refreshToken = undefined;
  user.sessionVersion = (user.sessionVersion || 0) + 1;
  await user.save();

  logger.info('Password reset completed', { email: user.email });
  return { message: 'Password reset successfully. Please log in with your new password.' };
};

export const formatAuthResponse = (tokens) => ({
  user: {
    id: tokens.user.id || tokens.user._id?.toString(),
    name: tokens.user.name,
    email: tokens.user.email,
    phone: tokens.user.phone,
    role: tokens.user.role,
    avatar: tokens.user.avatar || tokens.user.profileImage || null,
    isVerified: tokens.user.isVerified,
  },
});

import { body } from 'express-validator';

const emailValidator = body('email').trim().isEmail().normalizeEmail().withMessage('Valid email is required');
const passwordValidator = body('password')
  .isLength({ min: 8 })
  .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])/)
  .withMessage('Password must be 8+ chars with upper, lower, number, and special character');

export const registerValidator = [
  body('name').optional().trim().isLength({ max: 100 }).escape(),
  body('firstName').optional().trim().isLength({ max: 60 }).escape(),
  body('lastName').optional().trim().isLength({ max: 60 }).escape(),
  emailValidator,
  body('phone').trim().notEmpty().isLength({ max: 20 }),
  body('profileImage').optional().trim().isLength({ max: 500 }),
  body('password').optional().custom((value) => {
    if (!value) return true;
    if (value.length < 8) throw new Error('Password must be at least 8 characters');
    return true;
  }),
];

export const loginValidator = [emailValidator, body('password').notEmpty()];

export const loginPasswordValidator = [
  emailValidator,
  body('password').notEmpty().withMessage('Password is required'),
];

export const otpRequestValidator = [
  body('identifier')
    .trim()
    .notEmpty()
    .isLength({ max: 120 })
    .withMessage('Email address or phone number is required')
    .custom((val) => {
      if (val.includes('@')) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(val)) {
          throw new Error('Please enter a valid email address');
        }
      }
      return true;
    }),
  body('role').optional().isIn(['user', 'admin']),
];

export const otpVerifyValidator = [
  body('identifier').trim().notEmpty().isLength({ max: 120 }),
  body('otp').trim().isLength({ min: 6, max: 6 }).isNumeric(),
  body('role').optional().isIn(['user', 'admin']),
];

export const forgotPasswordValidator = [emailValidator];

export const resetPasswordValidator = [
  body('token').notEmpty(),
  body('newPassword').custom((value, { req }) => {
    value = value || req.body.password;
    if (!value) throw new Error('New password is required');
    if (value.length < 8) throw new Error('Password must be at least 8 characters');
    if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])/.test(value)) {
      throw new Error('Password must include upper, lower, number, and special character');
    }
    return true;
  }),
];

export const updateProfileValidator = [
  body('name').optional().trim().isLength({ max: 100 }).escape(),
  body('phone').optional().trim().isLength({ max: 20 }),
  body('password').optional().isLength({ min: 8 }),
  body('avatar').optional().trim().isURL().withMessage('Avatar must be a valid URL'),
];

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, HelpCircle } from 'lucide-react';

interface BeforeAfterSliderProps {
  beforeImage: string;
  afterImage: string;
  title: string;
  subtitle?: string;
  beforeLabel?: string;
  afterLabel?: string;
}

export default function BeforeAfterSlider({
  beforeImage,
  afterImage,
  title,
  subtitle,
  beforeLabel = 'Before (Structure & Foundation)',
  afterLabel = 'After (Completed Masterpiece)'
}: BeforeAfterSliderProps) {
  const [sliderPosition, setSliderPosition] = useState(50);
  const [isDragging, setIsDragging] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMove = (clientX: number) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = clientX - rect.left;
    let position = (x / rect.width) * 100;
    if (position < 0) position = 0;
    if (position > 100) position = 100;
    setSliderPosition(position);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    handleMove(e.clientX);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!isDragging) return;
    if (e.touches.length > 0) {
      handleMove(e.touches[0].clientX);
    }
  };

  const handleMouseDown = () => {
    setIsDragging(true);
  };

  const handleTouchStart = () => {
    setIsDragging(true);
  };

  useEffect(() => {
    const handleMouseUp = () => {
      setIsDragging(false);
    };

    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('touchend', handleMouseUp);

    return () => {
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('touchend', handleMouseUp);
    };
  }, []);

  return (
    <div className="w-full max-w-5xl mx-auto py-10">
      {/* Title */}
      <div className="text-center mb-8">
        <span className="inline-block px-3 py-1 text-[10px] font-bold uppercase tracking-widest text-brand-gold bg-brand-gold/10 rounded-full mb-3">
          Structural Transformation
        </span>
        <h3 className="font-display text-2xl md:text-3xl font-bold text-white mb-2">
          {title}
        </h3>
        {subtitle && (
          <p className="font-serif text-brand-on-surface-variant/60 text-sm md:text-base italic max-w-xl mx-auto">
            {subtitle}
          </p>
        )}
      </div>

      {/* Slider Container */}
      <div
        ref={containerRef}
        onMouseMove={handleMouseMove}
        onTouchMove={handleTouchMove}
        className="relative aspect-[16/9] w-full overflow-hidden rounded-2xl border border-white/10 shadow-2xl bg-brand-surface-lowest select-none before-after-container"
      >
        {/* AFTER IMAGE (Background) */}
        <img
          src={afterImage}
          alt="Completed structure"
          className="absolute inset-0 w-full h-full object-cover pointer-events-none"
          loading="lazy"
          decoding="async"
        />
        <div className="absolute bottom-4 right-6 z-20 glass-gold px-4 py-1.5 rounded-lg">
          <span className="font-display text-brand-gold text-[10px] uppercase tracking-widest font-bold">
            {afterLabel}
          </span>
        </div>

        {/* BEFORE IMAGE (Foreground, clipped) */}
        <div
          className="absolute inset-0 w-full h-full overflow-hidden pointer-events-none"
          style={{ clipPath: `polygon(0 0, ${sliderPosition}% 0, ${sliderPosition}% 100%, 0 100%)` }}
        >
          <img
            src={beforeImage}
            alt="Structure under construction"
            className="absolute inset-0 w-full h-full object-cover pointer-events-none"
            style={{ width: containerRef.current?.getBoundingClientRect().width }}
            loading="lazy"
            decoding="async"
          />
          <div className="absolute bottom-4 left-6 z-20 bg-brand-surface-lowest/90 border border-white/10 px-4 py-1.5 rounded-lg">
            <span className="font-display text-white/60 text-[10px] uppercase tracking-widest font-bold">
              {beforeLabel}
            </span>
          </div>
        </div>

        {/* DRAG HANDLE VERTICAL LINE */}
        <div
          onMouseDown={handleMouseDown}
          onTouchStart={handleTouchStart}
          className="absolute top-0 bottom-0 w-1 bg-brand-gold cursor-ew-resize z-30 flex items-center justify-center before-after-handle"
          style={{ left: `${sliderPosition}%` }}
        >
          {/* Handle Circle */}
          <div className="w-10 h-10 rounded-full bg-brand-gold border-4 border-[#0a0f18] shadow-2xl flex items-center justify-center text-[#0a0f18] hover:scale-110 active:scale-95 transition-transform">
            <svg
              className="w-4 h-4 fill-current"
              viewBox="0 0 24 24"
            >
              <path d="M14 6l-6 6 6 6v-12z M10 18l6-6-6-6v12z" />
            </svg>
          </div>
        </div>
      </div>

      {/* Guide text */}
      <p className="text-center text-[10px] text-brand-on-surface-variant/40 uppercase tracking-[0.2em] mt-4 flex items-center justify-center gap-1.5">
        <Sparkles size={10} className="text-brand-gold" /> Drag the center slider left and right to compare construction phases
      </p>
    </div>
  );
}

import HCaptchaWidget from './HCaptchaWidget';
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import {
  X, Calendar, Clock, User, Phone, Mail, FileText, CheckCircle, Send, Loader2
} from 'lucide-react';
import { apiFetch } from '../utils/api';

interface BookConsultationModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialService?: string;
}

const TIME_SLOTS = [
  { label: 'Morning', sub: '9:00 AM – 12:00 PM', value: '9:00 AM' },
  { label: 'Afternoon', sub: '12:00 PM – 4:00 PM', value: '1:00 PM' },
  { label: 'Evening', sub: '4:00 PM – 7:00 PM', value: '5:00 PM' },
];

const SERVICES = [
  'Architectural Design',
  'Structural Engineering',
  'Interior Architecture',
  '3D Elevation Rendering',
  'Full Turnkey Construction',
  'Site Visit Consultation',
  'Vastu Planning',
];

export default function BookConsultationModal({
  isOpen,
  onClose,
  initialService,
}: BookConsultationModalProps) {
  const [step, setStep] = useState<'form' | 'success'>('form');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [captchaToken, setCaptchaToken] = useState('');
  const [captchaAttempt, setCaptchaAttempt] = useState(0);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [service, setService] = useState(initialService || SERVICES[0]);
  const [date, setDate] = useState('');
  const [timeSlot, setTimeSlot] = useState(TIME_SLOTS[0].value);
  const [notes, setNotes] = useState('');

  const today = new Date().toISOString().split('T')[0];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email || !phone || !date) {
      setError('Please fill in all required fields.');
      return;
    }
    setError(null);
    setLoading(true);

    try {
      const res = await apiFetch('/api/appointments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 'h-captcha-response': captchaToken,
          name,
          email,
          phone,
          service,
          date,
          time: timeSlot,
          preferredDate: date,
          preferredTime: timeSlot,
          notes,
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.message || 'Submission failed. Please try again.');
      }

      setStep('success');
      // Reset form
      setName(''); setEmail(''); setPhone('');
      setDate(''); setNotes('');
      setService(SERVICES[0]);
      setTimeSlot(TIME_SLOTS[0].value);
    } catch (err: any) {
      setError(err.message || 'Server error. Please try again.');
    } finally {
      setCaptchaToken(''); setCaptchaAttempt(value => value + 1);
      setLoading(false);
    }
  };

  const handleClose = () => {
    setStep('form');
    setError(null);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[160] flex items-center justify-center p-4 bg-brand-surface-lowest/90 backdrop-blur-md"
