import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { ChevronLeft, ChevronRight, X, ZoomIn, Layers } from 'lucide-react';
import { GALLERY_DATA } from '../data';

type GalleryFilter = 'All' | 'Exterior' | 'Interior' | 'Construction' | 'Completed Projects' | 'Ongoing Projects';

export default function VisualPortfolio() {
  const [activeFilter, setActiveFilter] = useState<GalleryFilter>('All');
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);

  const filters: GalleryFilter[] = ['All', 'Exterior', 'Interior', 'Construction', 'Completed Projects', 'Ongoing Projects'];

  const getGalleryCategory = (item: (typeof GALLERY_DATA)[number]): GalleryFilter => {
    const text = `${item.title} ${item.category} ${item.desc}`.toLowerCase();
    if (text.includes('interior') || text.includes('kitchen') || text.includes('bedroom') || text.includes('living')) return 'Interior';
    if (text.includes('construction') || text.includes('frame') || text.includes('foundation') || text.includes('pour')) return 'Construction';
    if (text.includes('completed') || text.includes('finish') || text.includes('villa elevation')) return 'Completed Projects';
    if (text.includes('progress') || text.includes('active') || text.includes('site')) return 'Ongoing Projects';
    return 'Exterior';
  };

  const filteredItems = activeFilter === 'All'
    ? GALLERY_DATA
    : GALLERY_DATA.filter(item => getGalleryCategory(item) === activeFilter);

  // Keyboard navigation for Lightbox
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (lightboxIndex === null) return;
      if (e.key === 'Escape') setLightboxIndex(null);
      if (e.key === 'ArrowRight') handleNext();
      if (e.key === 'ArrowLeft') handlePrev();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [lightboxIndex, filteredItems]);

  const handlePrev = () => {
    if (lightboxIndex === null) return;
    setLightboxIndex((lightboxIndex - 1 + filteredItems.length) % filteredItems.length);
  };

  const handleNext = () => {
    if (lightboxIndex === null) return;
    setLightboxIndex((lightboxIndex + 1) % filteredItems.length);
  };

  return (
    <div className="text-brand-on-surface min-h-screen bg-brand-surface pt-28 pb-20 px-6 md:px-16">
      {/* Header Info */}
      <section className="max-w-7xl mx-auto text-center mb-16">
        <span className="inline-block px-3 py-1 text-[10px] font-bold uppercase tracking-widest text-brand-gold bg-brand-gold/10 rounded-full mb-4">
          Gallery
        </span>
        <h1 className="font-display text-4xl md:text-5xl font-bold tracking-tight text-white mb-4">
          Project Gallery
        </h1>
        <p className="text-sm text-brand-on-surface-variant max-w-md mx-auto font-serif italic">
          Real project images from exterior, interior, construction, completed, and ongoing work.
        </p>
        <div className="gold-line mt-8 w-24 mx-auto" />
      </section>

      {/* Filter Tabs */}
      <section className="max-w-7xl mx-auto mb-12 flex justify-center">
        <div className="flex flex-wrap gap-2 justify-center bg-brand-surface-container/30 border border-white/5 p-1.5 rounded-2xl">
          {filters.map((f) => (
            <button
              key={f}
              onClick={() => setActiveFilter(f)}
              aria-pressed={activeFilter === f}
              aria-label={`Filter gallery by ${f}`}
              className={`px-5 py-2.5 rounded-xl text-[10px] font-bold font-display uppercase tracking-widest transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-brand-gold/50 ${
                activeFilter === f
                  ? 'bg-brand-gold text-[#0a0f18] shadow-lg shadow-brand-gold/10'
                  : 'bg-transparent text-brand-on-surface-variant/80 hover:text-white'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
      </section>

      {/* Gallery Grid */}
      <section className="max-w-7xl mx-auto">
        <motion.div 
          layout
          className="columns-1 sm:columns-2 lg:columns-3 gap-6 space-y-6 w-full"
        >
          <AnimatePresence mode="popLayout">
            {filteredItems.map((item, index) => (
              <motion.div
                key={item.id}
                layout
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ duration: 0.4, delay: index * 0.02 }}
                onClick={() => setLightboxIndex(index)}
                role="button"
                tabIndex={0}
                aria-label={`View ${item.title} in lightbox`}
                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') setLightboxIndex(index); }}
                className="break-inside-avoid relative group rounded-2xl overflow-hidden border border-white/5 bg-brand-surface-container cursor-pointer shadow-lg hover:shadow-2xl hover:border-brand-gold/20 transition-all duration-300 hover:-translate-y-1 block focus:outline-none focus:ring-2 focus:ring-brand-gold/50"
              >
                {/* Image */}
                <div className="relative overflow-hidden w-full h-auto">
                  <img
                    src={item.imageUrl}
                    alt={item.alt}
                    className="w-full object-cover transition-transform duration-700 group-hover:scale-103"
                    loading="lazy"
                    decoding="async"
                  />
                  {/* Hover Overlay */}
                  <div className="absolute inset-0 bg-[#050a12]/85 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-between p-6 z-10">
                    <div className="flex justify-between items-center">
                      <span className="px-2.5 py-1 bg-brand-gold/10 border border-brand-gold/30 rounded-lg text-[9px] font-bold uppercase tracking-wider text-brand-gold">
                        {getGalleryCategory(item)}
                      </span>
                      <span className="p-2 bg-brand-surface-container/80 backdrop-blur rounded-full text-white hover:text-brand-gold transition-colors border border-white/10">
                        <ZoomIn size={14} />
                      </span>
                    </div>

                    <div>
                      <h3 className="font-display text-sm font-bold text-white mb-2 uppercase tracking-wider">
                        {item.title}
                      </h3>
                      <p className="font-serif text-[11px] text-brand-on-surface-variant/80 leading-relaxed line-clamp-2">
                        {item.desc}
                      </p>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </motion.div>
      </section>

      {/* Lightbox Modal Component */}
      <AnimatePresence>
        {lightboxIndex !== null && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[200] bg-[#050a12]/98 backdrop-blur-lg flex items-center justify-center p-4"
            role="dialog"
            aria-modal="true"
            aria-label="Image Lightbox"
          >
            {/* Main Container */}
            <motion.div 
              initial={{ scale: 0.95, y: 10 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.95, y: 10 }}
              className="relative max-w-5xl w-full flex flex-col md:flex-row bg-brand-surface-container rounded-2xl overflow-hidden border border-white/10 shadow-2xl max-h-[90vh]"
            >
              {/* Close Button */}
              <button
                onClick={() => setLightboxIndex(null)}
                className="absolute top-4 right-4 md:top-6 md:right-6 z-[210] p-2 bg-brand-surface-lowest/80 backdrop-blur rounded-full text-brand-on-surface-variant hover:text-white hover:bg-white/10 transition-all border border-white/10"
                aria-label="Close Lightbox"
              >
                <X size={20} />
              </button>

              {/* Left Column: Image Viewer */}
              <div className="relative w-full md:w-8/12 bg-black/40 flex items-center justify-center min-h-[40vh] md:min-h-[60vh] max-h-[70vh]">
                <img
                  src={filteredItems[lightboxIndex].imageUrl}
                  alt={filteredItems[lightboxIndex].alt}
                  className="w-full h-full object-contain max-h-[65vh] p-2"
                  loading="lazy"
                  decoding="async"
                />

                {/* Navigation Arrows */}
                <button
                  onClick={(e: React.MouseEvent) => { e.stopPropagation(); handlePrev(); }}
                  className="absolute left-4 p-2.5 bg-brand-surface-lowest/70 backdrop-blur rounded-full text-brand-on-surface-variant hover:text-white hover:bg-white/10 hover:scale-105 transition-all border border-white/10"
                  aria-label="Previous Project"
                >
                  <ChevronLeft size={20} />
                </button>
                <button
                  onClick={(e: React.MouseEvent) => { e.stopPropagation(); handleNext(); }}
                  className="absolute right-4 p-2.5 bg-brand-surface-lowest/70 backdrop-blur rounded-full text-brand-on-surface-variant hover:text-white hover:bg-white/10 hover:scale-105 transition-all border border-white/10"
                  aria-label="Next Project"
                >
                  <ChevronRight size={20} />
                </button>
              </div>

              {/* Right Column: Architectural Metadata */}
              <div className="w-full md:w-4/12 p-8 flex flex-col justify-between bg-brand-surface-container border-t md:border-t-0 md:border-l border-white/10 overflow-y-auto max-h-[40vh] md:max-h-none">
                <div>
                  <span className="inline-block px-2.5 py-1 bg-brand-gold/10 border border-brand-gold/30 rounded-lg font-display text-[9px] font-bold uppercase tracking-wider text-brand-gold mb-4">
                    {getGalleryCategory(filteredItems[lightboxIndex])}
                  </span>
                  <h3 className="font-display text-lg font-bold text-white mb-3 uppercase tracking-wide">
                    {filteredItems[lightboxIndex].title}
                  </h3>
                  <p className="font-serif text-xs text-brand-on-surface-variant/90 leading-relaxed mb-6 font-light">
                    {filteredItems[lightboxIndex].desc}
                  </p>
                </div>

                <div className="border-t border-white/5 pt-6 mt-6">
                  <div className="flex items-center gap-3 text-xs text-brand-on-surface-variant/80 mb-4">
                    <span className="text-brand-gold"><Layers size={14} /></span>
                    <span>Real project image</span>
                  </div>
                  <div className="flex items-center justify-between text-[10px] font-mono uppercase tracking-wider text-brand-on-surface-variant/50">
                    <span>Record</span>
                    <span>{lightboxIndex + 1} of {filteredItems.length}</span>
                  </div>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Search, Download, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react';

export interface Column<T> {
  key: keyof T | string;
  label: string;
  render?: (value: any, row: T) => React.ReactNode;
  className?: string;
}

interface AdminTableProps<T> {
  columns: Column<T>[];
  data: T[];
  pageSize?: number;
  exportFilename?: string;
  loading?: boolean;
  emptyMessage?: string;
  actions?: (row: T) => React.ReactNode;
}

function getNestedValue(obj: any, key: string): any {
  return key.split('.').reduce((acc, k) => acc?.[k], obj);
}

function AdminTable<T extends { _id?: string; id?: string }>({
  columns,
  data,
  pageSize = 10,
  exportFilename = 'export',
  loading = false,
  emptyMessage = 'No records found',
  actions,
}: AdminTableProps<T>) {
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);

  const filtered = useMemo(() => {
    if (!searchQuery.trim()) return data;
    const q = searchQuery.toLowerCase();
    return data.filter((row) =>
      columns.some((col) => {
        const val = getNestedValue(row, col.key as string);
        return String(val ?? '').toLowerCase().includes(q);
      })
    );
  }, [data, searchQuery, columns]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const paginated = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(e.target.value);
    setCurrentPage(1);
  };

  const handleExport = () => {
    const headers = columns.map((c) => c.label).join(',');
    const rows = filtered.map((row) =>
      columns
        .map((col) => {
          const val = getNestedValue(row, col.key as string);
          const str = String(val ?? '').replace(/"/g, '""');
          return `"${str}"`;
        })
        .join(',')
    );
    const csv = [headers, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${exportFilename}_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Controls */}
      <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center justify-between">
        <div className="relative flex-1 max-w-sm">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-brand-on-surface-variant/50" />
          <input
            type="text"
            placeholder="Search..."
            value={searchQuery}
            onChange={handleSearch}
            className="w-full pl-9 pr-4 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40 placeholder:text-brand-on-surface-variant/40 transition-colors"
          />
        </div>
        <button
          onClick={handleExport}
          className="flex items-center gap-2 px-4 py-2.5 border border-brand-gold/20 text-brand-gold hover:bg-brand-gold hover:text-brand-surface text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all"
        >
          <Download size={13} />
          Export CSV
        </button>
      </div>

      {/* Table */}
      <div className="overflow-x-auto rounded-xl border border-white/8">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-brand-surface-container border-b border-white/8">
              {columns.map((col) => (
                <th
                  key={col.key as string}
                  className={`px-4 py-3 text-left text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant ${col.className ?? ''}`}
                >
                  {col.label}
                </th>
              ))}
              {actions && <th className="px-4 py-3 text-right text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Actions</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {loading ? (
              <tr>
                <td colSpan={columns.length + (actions ? 1 : 0)} className="py-12 text-center text-brand-on-surface-variant text-sm">
                  <div className="flex items-center justify-center gap-3">
                    <div className="w-5 h-5 border-2 border-brand-gold/30 border-t-brand-gold rounded-full animate-spin" />
                    Loading...
                  </div>
                </td>
              </tr>
            ) : paginated.length === 0 ? (
              <tr>
                <td colSpan={columns.length + (actions ? 1 : 0)} className="py-12 text-center text-brand-on-surface-variant/50 text-sm">
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              paginated.map((row, i) => (
                <tr key={(row as any)._id ?? (row as any).id ?? i} className="hover:bg-white/[0.02] transition-colors">
                  {columns.map((col) => (
                    <td key={col.key as string} className={`px-4 py-3 text-brand-on-surface ${col.className ?? ''}`}>
                      {col.render
                        ? col.render(getNestedValue(row, col.key as string), row)
                        : String(getNestedValue(row, col.key as string) ?? '—')}
                    </td>
                  ))}
                  {actions && (
                    <td className="px-4 py-3 text-right">
                      {actions(row)}
                    </td>
                  )}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="flex items-center justify-between text-xs text-brand-on-surface-variant">
        <span>
          Showing {Math.min((currentPage - 1) * pageSize + 1, filtered.length)}–{Math.min(currentPage * pageSize, filtered.length)} of {filtered.length}
        </span>
        <div className="flex items-center gap-1">
          <button onClick={() => setCurrentPage(1)} disabled={currentPage === 1} className="p-1.5 rounded-lg hover:bg-white/5 disabled:opacity-30 transition-colors">
            <ChevronsLeft size={14} />
          </button>
          <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="p-1.5 rounded-lg hover:bg-white/5 disabled:opacity-30 transition-colors">
            <ChevronLeft size={14} />
          </button>
          {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
            let page = i + 1;
            if (totalPages > 5) {
              if (currentPage <= 3) page = i + 1;
              else if (currentPage >= totalPages - 2) page = totalPages - 4 + i;
              else page = currentPage - 2 + i;
            }
            return (
              <button
                key={page}
                onClick={() => setCurrentPage(page)}
                className={`w-7 h-7 rounded-lg text-[11px] font-bold transition-colors ${currentPage === page ? 'bg-brand-gold text-brand-surface' : 'hover:bg-white/5'}`}
              >
                {page}
              </button>
            );
          })}
          <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="p-1.5 rounded-lg hover:bg-white/5 disabled:opacity-30 transition-colors">
            <ChevronRight size={14} />
          </button>
          <button onClick={() => setCurrentPage(totalPages)} disabled={currentPage === totalPages} className="p-1.5 rounded-lg hover:bg-white/5 disabled:opacity-30 transition-colors">
            <ChevronsRight size={14} />
          </button>
        </div>
      </div>
    </div>
  );
}

