import React, { useRef, useState } from 'react';
import { UploadCloud, X, FileText, Image as ImageIcon, Loader2 } from 'lucide-react';
import { apiFetch } from '../../utils/api';

interface FileUploadProps {
  value?: string;
  onChange: (url: string, publicId?: string) => void;
  fileType?: 'image' | 'pdf' | 'blueprint';
  label?: string;
  accept?: string;
  disabled?: boolean;
}

const FileUpload: React.FC<FileUploadProps> = ({
  value,
  onChange,
  fileType = 'image',
  label = 'Upload File',
  accept,
  disabled = false,
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);

  const acceptAttr = accept ?? (fileType === 'image' ? 'image/jpeg,image/png,image/webp' : 'application/pdf');

  const upload = async (file: File) => {
    setUploading(true);
    setError(null);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileType', fileType);
      const res = await apiFetch('/api/uploads', { method: 'POST', body: formData });
      const result = await res.json();
      if (!res.ok || !result.success) throw new Error(result.message || 'Upload failed');
      onChange(result.data.url, result.data.publicId);
    } catch (err: any) {
      setError(err.message ?? 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) upload(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) upload(file);
  };

  const isImage = fileType === 'image';

  return (
    <div className="space-y-2">
      {label && (
        <label className="block text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">
          {label}
        </label>
      )}

      {/* Preview */}
      {value && (
        <div className="relative inline-flex items-center gap-3 p-3 bg-brand-surface-container rounded-xl border border-white/8">
          {isImage ? (
            <img src={value} alt="Preview" className="w-16 h-16 rounded-lg object-cover" />
          ) : (
            <div className="w-12 h-12 bg-brand-gold/10 rounded-lg flex items-center justify-center">
              <FileText size={20} className="text-brand-gold" />
            </div>
          )}
          <div className="flex-1 min-w-0">
            <p className="text-xs text-white truncate">{value.split('/').pop()}</p>
            <p className="text-[10px] text-brand-on-surface-variant mt-0.5">Uploaded</p>
          </div>
          <button
            type="button"
            onClick={() => onChange('', '')}
            className="p-1 rounded-lg hover:bg-red-500/10 text-red-400 transition-colors"
          >
            <X size={14} />
          </button>
        </div>
      )}

      {/* Drop Zone */}
      <div
        onClick={() => !disabled && !uploading && inputRef.current?.click()}
        onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
        onDragLeave={() => setDragging(false)}
        onDrop={handleDrop}
        className={`flex flex-col items-center justify-center gap-3 p-6 border-2 border-dashed rounded-xl cursor-pointer transition-all ${
          dragging
            ? 'border-brand-gold/60 bg-brand-gold/5'
            : 'border-white/10 hover:border-brand-gold/30 hover:bg-white/[0.02]'
        } ${disabled || uploading ? 'opacity-50 cursor-not-allowed' : ''}`}
      >
        {uploading ? (
          <Loader2 size={24} className="text-brand-gold animate-spin" />
        ) : isImage ? (
          <ImageIcon size={24} className="text-brand-on-surface-variant" />
        ) : (
          <FileText size={24} className="text-brand-on-surface-variant" />
        )}
        <div className="text-center">
          <p className="text-xs text-brand-on-surface-variant">
            {uploading ? 'Uploading...' : (
              <>Drag & drop or <span className="text-brand-gold font-semibold">click to browse</span></>
            )}
          </p>
          <p className="text-[10px] text-brand-on-surface-variant/50 mt-1">
            {fileType === 'image' ? 'JPG, PNG, WEBP' : 'PDF only'} · Max {10}MB
          </p>
        </div>
        <UploadCloud size={16} className="text-brand-on-surface-variant/40" />
        <input
          ref={inputRef}
          type="file"
          accept={acceptAttr}
          onChange={handleFileChange}
          className="hidden"
          disabled={disabled || uploading}
        />
      </div>

      {error && (
        <p className="text-xs text-red-400 mt-1">{error}</p>
      )}
    </div>
  );
};

export default FileUpload;

// src/hooks/useScrollReveal.ts
import { useEffect, useRef } from 'react';
import gsap from 'gsap';

interface ScrollRevealOptions {
  threshold?: number;
  rootMargin?: string;
  className?: string;
  delay?: number;
}

export function useScrollReveal<T extends HTMLElement>(
  options: ScrollRevealOptions = {}
) {
  const ref = useRef<T>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const {
      threshold = 0.15,
      rootMargin = '0px 0px -60px 0px',
      className = 'revealed',
      delay = 0,
    } = options;

    // Set initial state for GSAP animation
    gsap.set(el, {
      opacity: 0,
      y: 40,
      filter: 'blur(10px)'
    });

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          el.classList.add(className);
          
          // GSAP reveal animation
          gsap.to(el, {
            opacity: 1,
            y: 0,
            filter: 'blur(0px)',
            duration: 1.2,
            delay: delay,
            ease: 'power3.out'
          });
          
          observer.disconnect();
        }
      },
      { threshold, rootMargin }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return ref;
}

export default useScrollReveal;

import React, { useState } from 'react';
import { motion } from 'motion/react';
import { ShieldCheck, Mail, AlertCircle, Loader2 } from 'lucide-react';
import { loginAdmin, verifyLoginOtp } from '../utils/auth';

interface AdminLoginProps {
  onLoginSuccess: () => void;
}

export default function AdminLogin({ onLoginSuccess }: AdminLoginProps) {
  const [identifier, setIdentifier] = useState('');
  const [otp, setOtp] = useState('');
  const [otpSentTo, setOtpSentTo] = useState('');
  const [otpChannel, setOtpChannel] = useState<'email' | 'phone' | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      if (otpSentTo) {
        await verifyLoginOtp(otpSentTo, otp, 'admin');
        onLoginSuccess();
        return;
      }

      const challenge = await loginAdmin(identifier);
      setOtpSentTo(challenge.identifier);
      setOtpChannel(challenge.channel);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Admin authentication failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-brand-surface px-4">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: [0.25, 1, 0.5, 1] }}
        className="w-full max-w-sm"
      >
        <div className="bg-brand-surface-high border border-white/8 rounded-2xl shadow-2xl overflow-hidden">
          <div className="bg-brand-gold px-8 py-6 flex flex-col items-center gap-2">
            <span className="p-3 bg-[#0a0f18]/20 rounded-xl">
              <ShieldCheck size={26} className="text-[#0a0f18]" />
            </span>
            <h1 className="font-display text-[#0a0f18] text-lg font-black uppercase tracking-[0.2em]">
              {otpSentTo ? 'Verify Admin' : 'Admin Portal'}
            </h1>
            <p className="font-display text-[#0a0f18]/60 text-[9px] uppercase tracking-widest">
              NVS Buildcon & Architects
            </p>
          </div>

          <form onSubmit={handleSubmit} className="px-8 py-8 space-y-5">
            {error && (
              <div className="flex items-center gap-2.5 p-3.5 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs">
                <AlertCircle size={14} className="shrink-0" />
                <span>{error}</span>
              </div>
            )}

            {otpSentTo && (
              <div className="flex items-start gap-2.5 p-3.5 bg-brand-gold/10 border border-brand-gold/20 rounded-xl text-brand-gold text-xs">
                <ShieldCheck size={14} className="shrink-0 mt-0.5" />
                <span>
                  Please enter the 6-digit OTP sent to <strong className="text-white">{otpSentTo}</strong>. Valid for 5 minutes.
                </span>
              </div>
            )}

            {!otpSentTo ? (
              <div className="space-y-1.5">
                <label htmlFor="admin-identifier" className="block font-display text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">
                  Email
                </label>
                <div className="relative">
                  <span className="absolute inset-y-0 left-3.5 flex items-center text-brand-on-surface-variant/40 pointer-events-none">
                    <Mail size={14} />
                  </span>
                  <input
                    id="admin-identifier"
                    type="text"
                    required
                    value={identifier}
                    onChange={(e) => setIdentifier(e.target.value)}
                    placeholder="admin@nvsbuildcon.com"
                    className="w-full pl-10 pr-4 py-3 text-sm rounded-xl bg-brand-surface-container border border-white/8 focus:outline-none focus:ring-2 focus:ring-brand-gold/40 focus:border-brand-gold/40 text-brand-on-surface placeholder:text-brand-on-surface/25 transition-all"
                  />
                </div>
              </div>
            ) : (
              <div className="space-y-1.5">
                <label htmlFor="admin-otp" className="block font-display text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">
                  OTP
                </label>
                <div className="relative">
                  <span className="absolute inset-y-0 left-3.5 flex items-center text-brand-on-surface-variant/40 pointer-events-none">
                    <ShieldCheck size={14} />
                  </span>
                  <input
                    id="admin-otp"
                    type="text"
                    inputMode="numeric"
                    maxLength={6}
                    required
                    value={otp}
                    onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                    placeholder="6-digit OTP"
                    className="w-full pl-10 pr-4 py-3 text-sm rounded-xl bg-brand-surface-container border border-white/8 focus:outline-none focus:ring-2 focus:ring-brand-gold/40 focus:border-brand-gold/40 text-brand-on-surface placeholder:text-brand-on-surface/25 transition-all"
                  />
                </div>
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full flex items-center justify-center gap-2 py-3.5 bg-brand-gold text-[#0a0f18] font-display text-[11px] font-black uppercase tracking-widest rounded-xl shadow-lg shadow-brand-gold/20 hover:scale-[1.02] disabled:opacity-60 disabled:cursor-not-allowed disabled:scale-100 transition-all duration-200 mt-2"
            >
              {loading ? <><Loader2 size={14} className="animate-spin" /> Please wait...</> : otpSentTo ? 'Verify & Sign In' : 'Send Admin OTP'}
            </button>
          </form>
        </div>
      </motion.div>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
