    New: 'bg-blue-500/10 text-blue-400',
    Pending: 'bg-amber-500/10 text-amber-400',
    'In Progress': 'bg-purple-500/10 text-purple-400',
    Contacted: 'bg-cyan-500/10 text-cyan-400',
    Completed: 'bg-emerald-500/10 text-emerald-400',
