            <button onClick={() => handleDelete(row._id)} className="p-1.5 rounded-lg bg-white/5 hover:bg-red-500/10 text-brand-on-surface-variant hover:text-red-400 transition-all"><Trash2 size={13} /></button>
          </div>
        )}
      />

      <AdminModal isOpen={modalOpen} onClose={() => setModalOpen(false)} title={editId ? 'Edit Project' : 'Add Project'} size="lg">
        <form onSubmit={handleSave} className="space-y-5">
          {error && <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-400 text-xs rounded-xl">{error}</div>}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Title *</label>
              <input required value={form.title} onChange={(e) => f('title', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40" placeholder="Project Title" />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Category</label>
              <select value={form.category} onChange={(e) => f('category', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40">
                {CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Location</label>
              <input value={form.location} onChange={(e) => f('location', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40" placeholder="City, State" />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Year</label>
              <input type="number" value={form.year} onChange={(e) => f('year', parseInt(e.target.value))} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40" />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Area</label>
              <input value={form.area} onChange={(e) => f('area', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40" placeholder="e.g. 2500 sq.ft" />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Status</label>
              <select value={form.status} onChange={(e) => f('status', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40">
                {STATUSES.map((s) => <option key={s} value={s}>{s.charAt(0).toUpperCase() + s.slice(1)}</option>)}
              </select>
            </div>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Description</label>
            <textarea rows={3} value={form.description} onChange={(e) => f('description', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40 resize-none" placeholder="Project description..." />
          </div>
          <FileUpload value={form.imageUrl} onChange={(url) => f('imageUrl', url)} fileType="image" label="Cover Image" />
          <div className="flex gap-3 pt-2">
            <button type="button" onClick={() => setModalOpen(false)} className="flex-1 py-2.5 border border-white/10 text-brand-on-surface-variant text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-white/5 transition-colors">Cancel</button>
            <button type="submit" disabled={saving} className="flex-1 py-2.5 bg-brand-gold text-brand-surface text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-brand-gold/80 transition-colors disabled:opacity-50">
              {saving ? 'Saving...' : (editId ? 'Update' : 'Create')}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default ProjectsManager;

import React, { useEffect, useState, useCallback } from 'react';
import { Plus, Pencil, Trash2, X } from 'lucide-react';
import { apiFetch } from '../../utils/api';
import AdminTable, { Column } from '../../components/admin/AdminTable';
import AdminModal from '../../components/admin/AdminModal';

interface Service {
  _id: string;
  title: string;
  description: string;
  icon: string;
  details: string[];
}

const EMPTY: Omit<Service, '_id'> = { title: '', description: '', icon: 'Compass', details: [] };
const ICONS = ['Compass', 'Layers', 'Landmark', 'Hammer', 'Wrench', 'Home', 'Building', 'Ruler', 'PenTool', 'Star'];

const ServicesManager: React.FC = () => {
  const [data, setData] = useState<Service[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState<Omit<Service, '_id'>>(EMPTY);
  const [editId, setEditId] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newDetail, setNewDetail] = useState('');

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiFetch('/api/services');
      const result = await res.json();
      if (result.success) setData(result.data);
    } catch {/* ignore */} finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const openCreate = () => { setForm(EMPTY); setEditId(null); setError(null); setNewDetail(''); setModalOpen(true); };
  const openEdit = (row: Service) => { const { _id, ...rest } = row; setForm(rest); setEditId(_id); setError(null); setNewDetail(''); setModalOpen(true); };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true); setError(null);
    try {
      const method = editId ? 'PUT' : 'POST';
      const url = editId ? `/api/services/${editId}` : '/api/services';
      const res = await apiFetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) });
      const result = await res.json();
      if (!res.ok) throw new Error(result.message || 'Save failed');
      setModalOpen(false); fetchData();
    } catch (err: any) { setError(err.message); } finally { setSaving(false); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this service?')) return;
    await apiFetch(`/api/services/${id}`, { method: 'DELETE' });
    fetchData();
  };

  const addDetail = () => {
    if (newDetail.trim()) {
      setForm(p => ({ ...p, details: [...p.details, newDetail.trim()] }));
      setNewDetail('');
    }
  };

  const removeDetail = (idx: number) => setForm(p => ({ ...p, details: p.details.filter((_, i) => i !== idx) }));

  const columns: Column<Service>[] = [
    { key: 'icon', label: 'Icon', render: (v) => <span className="text-[10px] font-mono text-brand-gold bg-brand-gold/10 px-2 py-1 rounded-lg">{v}</span> },
    { key: 'title', label: 'Title', render: (v) => <span className="font-semibold text-white">{v}</span> },
    { key: 'description', label: 'Description', className: 'max-w-xs', render: (v) => <span className="text-brand-on-surface-variant truncate block max-w-xs">{v}</span> },
    { key: 'details', label: 'Features', render: (v) => <span className="text-xs text-brand-on-surface-variant">{(v as string[]).length} items</span> },
  ];

  const f = (k: keyof typeof form, v: any) => setForm(p => ({ ...p, [k]: v }));

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-display text-lg font-black uppercase tracking-widest text-brand-on-surface">Services</h2>
          <p className="text-xs text-brand-on-surface-variant mt-0.5">{data.length} services</p>
        </div>
        <button onClick={openCreate} className="flex items-center gap-2 px-4 py-2.5 bg-brand-gold text-brand-surface text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-brand-gold/80 transition-colors">
          <Plus size={14} /> Add Service
        </button>
      </div>
      <AdminTable columns={columns} data={data} loading={loading} exportFilename="services" emptyMessage="No services yet."
        actions={(row) => (
          <div className="flex items-center gap-2 justify-end">
            <button onClick={() => openEdit(row)} className="p-1.5 rounded-lg bg-white/5 hover:bg-brand-gold/10 text-brand-on-surface-variant hover:text-brand-gold transition-all"><Pencil size={13} /></button>
            <button onClick={() => handleDelete(row._id)} className="p-1.5 rounded-lg bg-white/5 hover:bg-red-500/10 text-brand-on-surface-variant hover:text-red-400 transition-all"><Trash2 size={13} /></button>
          </div>
        )}
      />
      <AdminModal isOpen={modalOpen} onClose={() => setModalOpen(false)} title={editId ? 'Edit Service' : 'Add Service'} size="md">
        <form onSubmit={handleSave} className="space-y-4">
          {error && <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-400 text-xs rounded-xl">{error}</div>}
          <div className="space-y-1.5">
            <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Title *</label>
            <input required value={form.title} onChange={(e) => f('title', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40" />
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Icon</label>
            <select value={form.icon} onChange={(e) => f('icon', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40">
              {ICONS.map((ic) => <option key={ic} value={ic}>{ic}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Description *</label>
            <textarea required rows={3} value={form.description} onChange={(e) => f('description', e.target.value)} className="w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40 resize-none" />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant">Features</label>
            <div className="flex gap-2">
              <input value={newDetail} onChange={(e) => setNewDetail(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addDetail(); }}} placeholder="Add a feature..." className="flex-1 px-3 py-2 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40" />
              <button type="button" onClick={addDetail} className="px-4 py-2 bg-brand-gold/10 text-brand-gold text-xs font-bold rounded-xl hover:bg-brand-gold/20 transition-colors">Add</button>
            </div>
            <div className="flex flex-wrap gap-2">
              {form.details.map((d, i) => (
                <span key={i} className="flex items-center gap-1.5 text-[10px] font-bold px-2.5 py-1.5 rounded-full bg-white/5 text-brand-on-surface-variant">
                  {d}
                  <button type="button" onClick={() => removeDetail(i)} className="hover:text-red-400 transition-colors"><X size={10} /></button>
                </span>
              ))}
            </div>
          </div>
          <div className="flex gap-3 pt-2">
            <button type="button" onClick={() => setModalOpen(false)} className="flex-1 py-2.5 border border-white/10 text-brand-on-surface-variant text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-white/5 transition-colors">Cancel</button>
            <button type="submit" disabled={saving} className="flex-1 py-2.5 bg-brand-gold text-brand-surface text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-brand-gold/80 transition-colors disabled:opacity-50">
              {saving ? 'Saving...' : (editId ? 'Update' : 'Create')}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default ServicesManager;

import React, { useEffect, useState, useCallback } from 'react';
import { Save, RefreshCw } from 'lucide-react';
import { apiFetch } from '../../utils/api';

interface Settings {
  companyPhone: string;
  whatsappNumber: string;
  emailForNotifications: string;
  contactEmail: string;
  contactPhone: string;
  address: string;
  heroTitle: string;
  heroSubtitle: string;
  metaTitle: string;
  metaDescription: string;
  metaKeywords: string;
  projectsCount: number;
  citiesCount: number;
  yearsCount: number;
  planningPrice: number;
  constructionPrice: number;
  pricingDisclaimer: string;
}

const EMPTY: Settings = {
  companyPhone: '', whatsappNumber: '', emailForNotifications: '', contactEmail: '',
  contactPhone: '', address: '', heroTitle: '', heroSubtitle: '',
  metaTitle: '', metaDescription: '', metaKeywords: '',
  projectsCount: 50, citiesCount: 12, yearsCount: 15,
  planningPrice: 5, constructionPrice: 1100,
  pricingDisclaimer: '',
};

type TabId = 'contact' | 'homepage' | 'seo' | 'pricing';

const TABS: { id: TabId; label: string }[] = [
  { id: 'contact', label: 'Contact Details' },
  { id: 'homepage', label: 'Homepage' },
  { id: 'seo', label: 'SEO & Meta' },
  { id: 'pricing', label: 'Pricing & Rates' },
];

const SettingsManager: React.FC = () => {
  const [form, setForm] = useState<Settings>(EMPTY);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabId>('contact');

  const fetchSettings = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiFetch('/api/settings');
      const result = await res.json();
      if (result.success) setForm({ ...EMPTY, ...result.data });
    } catch {/* ignore */} finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchSettings(); }, [fetchSettings]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true); setError(null); setSuccessMsg(null);
    try {
      const res = await apiFetch('/api/settings', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      });
      const result = await res.json();
      if (!res.ok) throw new Error(result.message || 'Save failed');
      setSuccessMsg('Settings saved successfully!');
      setTimeout(() => setSuccessMsg(null), 3000);
    } catch (err: any) { setError(err.message); } finally { setSaving(false); }
  };

  const f = (k: keyof Settings, v: any) => setForm(p => ({ ...p, [k]: v }));

  const inputClass = "w-full px-3 py-2.5 bg-brand-surface-container border border-white/8 text-sm text-white rounded-xl focus:outline-none focus:border-brand-gold/40 placeholder:text-brand-on-surface-variant/30 transition-colors";
  const labelClass = "block text-[10px] font-bold uppercase tracking-widest text-brand-on-surface-variant mb-1.5";

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <div className="w-8 h-8 border-2 border-brand-gold/30 border-t-brand-gold rounded-full animate-spin" />
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-display text-lg font-black uppercase tracking-widest text-brand-on-surface">Site Settings</h2>
          <p className="text-xs text-brand-on-surface-variant mt-0.5">Manage all website configuration</p>
        </div>
        <button onClick={fetchSettings} className="p-2 rounded-xl border border-white/10 text-brand-on-surface-variant hover:text-white hover:bg-white/5 transition-colors">
          <RefreshCw size={14} />
        </button>
      </div>

      {/* Tabs */}
      <div className="flex gap-1 p-1 bg-brand-surface-container rounded-xl border border-white/8">
        {TABS.map((tab) => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id)}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-widest rounded-lg transition-all ${activeTab === tab.id ? 'bg-brand-gold text-brand-surface shadow-sm' : 'text-brand-on-surface-variant hover:text-white'}`}>
            {tab.label}
          </button>
        ))}
      </div>

      <form onSubmit={handleSave} className="space-y-5">
        {successMsg && <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-xs rounded-xl">{successMsg}</div>}
        {error && <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-400 text-xs rounded-xl">{error}</div>}

        {activeTab === 'contact' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
            <div><label className={labelClass}>Company Phone</label><input value={form.companyPhone} onChange={(e) => f('companyPhone', e.target.value)} className={inputClass} /></div>
            <div><label className={labelClass}>WhatsApp Number</label><input value={form.whatsappNumber} onChange={(e) => f('whatsappNumber', e.target.value)} className={inputClass} /></div>
            <div><label className={labelClass}>Contact Phone</label><input value={form.contactPhone} onChange={(e) => f('contactPhone', e.target.value)} className={inputClass} /></div>
            <div><label className={labelClass}>Contact Email</label><input type="email" value={form.contactEmail} onChange={(e) => f('contactEmail', e.target.value)} className={inputClass} /></div>
            <div><label className={labelClass}>Notification Email</label><input type="email" value={form.emailForNotifications} onChange={(e) => f('emailForNotifications', e.target.value)} className={inputClass} /></div>
            <div className="sm:col-span-2"><label className={labelClass}>Address</label><textarea rows={2} value={form.address} onChange={(e) => f('address', e.target.value)} className={inputClass + ' resize-none'} /></div>
          </div>
        )}

        {activeTab === 'homepage' && (
          <div className="space-y-5">
            <div><label className={labelClass}>Hero Heading</label><input value={form.heroTitle} onChange={(e) => f('heroTitle', e.target.value)} className={inputClass} /></div>
            <div><label className={labelClass}>Hero Subheading</label><textarea rows={3} value={form.heroSubtitle} onChange={(e) => f('heroSubtitle', e.target.value)} className={inputClass + ' resize-none'} /></div>
            <div className="grid grid-cols-3 gap-4">
              <div><label className={labelClass}>Projects Count</label><input type="number" value={form.projectsCount} onChange={(e) => f('projectsCount', parseInt(e.target.value))} className={inputClass} /></div>
              <div><label className={labelClass}>Cities Count</label><input type="number" value={form.citiesCount} onChange={(e) => f('citiesCount', parseInt(e.target.value))} className={inputClass} /></div>
              <div><label className={labelClass}>Years Count</label><input type="number" value={form.yearsCount} onChange={(e) => f('yearsCount', parseInt(e.target.value))} className={inputClass} /></div>
            </div>
          </div>
        )}

        {activeTab === 'seo' && (
          <div className="space-y-5">
            <div><label className={labelClass}>Meta Title</label><input value={form.metaTitle} onChange={(e) => f('metaTitle', e.target.value)} className={inputClass} placeholder="NVS Buildcon | Premium Architecture & Construction" /></div>
            <div><label className={labelClass}>Meta Description</label><textarea rows={3} value={form.metaDescription} onChange={(e) => f('metaDescription', e.target.value)} className={inputClass + ' resize-none'} /></div>
            <div><label className={labelClass}>Meta Keywords (comma separated)</label><input value={form.metaKeywords} onChange={(e) => f('metaKeywords', e.target.value)} className={inputClass} /></div>
            <div className="p-4 bg-brand-gold/5 border border-brand-gold/10 rounded-xl">
              <p className="text-[10px] font-bold uppercase tracking-widest text-brand-gold mb-2">SEO Preview</p>
              <div className="space-y-1">
                <p className="text-sm font-semibold text-blue-400">{form.metaTitle || 'Page Title'}</p>
                <p className="text-xs text-green-500">nvsbuildcon.com</p>
                <p className="text-xs text-brand-on-surface-variant leading-relaxed">{form.metaDescription?.substring(0, 160) || 'Page description...'}</p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'pricing' && (
          <div className="space-y-5">
            <div className="grid grid-cols-2 gap-5">
              <div>
                <label className={labelClass}>Planning Price (₹/sq.ft)</label>
                <input type="number" value={form.planningPrice} onChange={(e) => f('planningPrice', parseFloat(e.target.value))} className={inputClass} />
                <p className="text-[10px] text-brand-on-surface-variant/50 mt-1">Used in Price Calculator</p>
              </div>
              <div>
                <label className={labelClass}>Construction Price (₹/sq.ft)</label>
                <input type="number" value={form.constructionPrice} onChange={(e) => f('constructionPrice', parseFloat(e.target.value))} className={inputClass} />
                <p className="text-[10px] text-brand-on-surface-variant/50 mt-1">Used in Price Calculator</p>
              </div>
            </div>
            <div>
              <label className={labelClass}>Pricing Disclaimer</label>
              <textarea rows={3} value={form.pricingDisclaimer} onChange={(e) => f('pricingDisclaimer', e.target.value)} className={inputClass + ' resize-none'} />
            </div>
            <div className="p-4 bg-brand-gold/5 border border-brand-gold/10 rounded-xl">
              <p className="text-[10px] font-bold uppercase tracking-widest text-brand-gold mb-2">Rate Preview</p>
              <div className="grid grid-cols-2 gap-3 text-sm">
                <div>
                  <p className="text-brand-on-surface-variant text-xs">Planning Rate</p>
                  <p className="text-white font-bold">₹{form.planningPrice}/sq.ft</p>
                </div>
                <div>
                  <p className="text-brand-on-surface-variant text-xs">Construction Rate</p>
                  <p className="text-white font-bold">₹{form.constructionPrice}/sq.ft</p>
                </div>
              </div>
            </div>
          </div>
        )}

        <button type="submit" disabled={saving} className="flex items-center gap-2 px-6 py-3 bg-brand-gold text-brand-surface text-[10px] font-bold uppercase tracking-widest rounded-xl hover:bg-brand-gold/80 transition-colors disabled:opacity-50">
          <Save size={14} />
          {saving ? 'Saving...' : 'Save Changes'}
        </button>
      </form>
    </div>
  );
};

export default SettingsManager;

